import os
import random
import struct
from typing import List

# Target data type: arbitrary bytes
# Provide varied but valid byte buffers for multiple consumers (strings, octet strings, BER-like, Ethernet frames).

MAX_TOTAL = 4096


def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(max(0, n)))


def _ascii_text(r: random.Random, min_len: int, max_len: int) -> bytes:
    length = r.randint(min_len, max_len)
    alphabet = (
        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_./:"  # path-ish
        b" ,;[]{}()@!#$%^&*"  # punctuation
    )
    s = bytearray()
    for _ in range(length):
        s.append(alphabet[r.randrange(len(alphabet))])
    # Sprinkle NULs only if non-empty
    if len(s) > 0:
        for _ in range(r.randint(0, max(1, length // 16))):
            if len(s) == 0:
                break
            pos = r.randrange(len(s))
            s[pos] = 0
    return bytes(s)


def _ber_tlv(r: random.Random, tag: int, payload: bytes) -> bytes:
    L = len(payload)
    if L < 0x80:
        return bytes([tag, L]) + payload
    else:
        if L <= 0xFF:
            return bytes([tag, 0x81, L]) + payload
        elif L <= 0xFFFF:
            return bytes([tag, 0x82, (L >> 8) & 0xFF, L & 0xFF]) + payload
        else:
            L = min(L, 0xFFFFFF)
            return bytes([tag, 0x83, (L >> 16) & 0xFF, (L >> 8) & 0xFF, L & 0xFF]) + payload


def _ber_bundle(r: random.Random) -> bytes:
    parts: List[bytes] = []
    for _ in range(r.randint(2, 5)):
        tag = r.choice([0x30, 0x31, 0xA0, 0xA1, 0x80, 0x81, 0x04, 0x05, 0x16, 0x1E, 0x09, 0x0F, 0x02])
        if r.random() < 0.3:
            inner = _rand_bytes(r, r.randint(0, 32))
        elif r.random() < 0.6:
            inner = _ascii_text(r, 0, 32)
        else:
            inner = _ber_tlv(r, r.choice([0x04, 0x02, 0x16, 0x30]), _rand_bytes(r, r.randint(0, 24)))
        parts.append(_ber_tlv(r, tag, inner))
    payload = b"".join(parts)
    return _ber_tlv(r, 0x30, payload)


def _ethernet_frame_like(r: random.Random, payload_len: int, eth_type: int = 0x88B8) -> bytes:
    # 6B dst, 6B src, 2B type, payload, pad to >=60, cap to 1500
    dst = _rand_bytes(r, 6)
    src = _rand_bytes(r, 6)
    if r.random() < 0.5 and len(dst) >= 1:
        dst = bytes([dst[0] | 0x01]) + dst[1:]
    hdr = dst + src + struct.pack('!H', eth_type)
    payload = _rand_bytes(r, payload_len)
    frame = hdr + payload
    if len(frame) < 60:
        frame += b"\x00" * (60 - len(frame))
    return frame[:1500]


def _udp_like_payload(r: random.Random, total_len: int) -> bytes:
    parts = []
    remaining = max(0, total_len)
    while remaining > 0:
        if r.random() < 0.4:
            chunk = _ascii_text(r, 1, min(64, remaining))
        else:
            chunk = _rand_bytes(r, min(64, remaining))
        parts.append(chunk)
        remaining -= len(chunk)
    return b"".join(parts)


def _mac_seeds_block(r: random.Random, count: int) -> bytes:
    b = bytearray()
    for _ in range(max(0, count)):
        b += _rand_bytes(r, 6)
    return bytes(b)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    chunks: List[bytes] = []

    # 1) Visible/MMS string friendly region (0-255)
    chunks.append(_ascii_text(r, 0, 255))

    # 2) Octet string region with explicit size prefixes to aid slicing
    for sz in [0, 1, 16, 64, 127, 128]:
        payload = _rand_bytes(r, sz)
        chunks.append(struct.pack('!H', sz) + payload)

    # 3) BER-like bundle for MmsValue_decodeMmsData
    chunks.append(_ber_bundle(r)[:512])

    # 4) Ethernet frame-like segments (60..1500)
    frame1 = _ethernet_frame_like(r, r.randint(0, 200), 0x88B8)
    frame2 = _ethernet_frame_like(r, r.randint(200, 1000), 0x0800)
    chunks.extend([frame1, frame2])

    # 5) UDP/TCP payload region up to 1024
    chunks.append(_udp_like_payload(r, r.randint(32, 256)))
    chunks.append(_udp_like_payload(r, r.randint(0, 1024)))

    # 6) MAC/VLAN seeds for GoosePublisher params
    vlan_prio = bytes([r.randrange(8)])
    vlan_id = struct.pack('!H', r.randrange(4095))
    app_id = struct.pack('!H', r.randrange(0, 65536))
    chunks.append(vlan_prio + vlan_id + app_id + _mac_seeds_block(r, 4))

    # 7) Additional ASCII including interface-like names
    iface = b"eth" + bytes([ord('0') + r.randrange(10)])
    pathish_tail = _ascii_text(r, 0, 32)
    chunks.extend([iface, b"/tmp/iec/" + pathish_tail])

    # 8) Boundary-size random blocks for generic send/write
    for sz in [0, 60, 128, 255, 512, 1024, 1500]:
        chunks.append(_rand_bytes(r, sz))

    # 9) Another BER bundle
    chunks.append(_ber_bundle(r)[:512])

    # 10) Small bytes for control fields, ports, etc.
    small = bytearray()
    for _ in range(16):
        small += struct.pack('!H', r.randrange(10000, 65535))
    chunks.append(bytes(small))

    out = b"".join(chunks)
    if len(out) > MAX_TOTAL:
        out = out[:MAX_TOTAL]

    return out

import random
import struct
import string

# Target data type: arbitrary string (null-terminated C string), used for many identifiers
# Our generator will emit a bytes buffer that, when consumed by FUZZ_PARAM_STR and
# FUZZ_PARAM_FILENAME in various stubs, yields useful, varied, and valid strings.
# Strategy:
# - Compose multiple NUL-terminated strings back-to-back so the fuzzing engine can
#   slice/consume several FUZZ_PARAM_STR calls from a single initial buffer.
# - Include a mix of patterns to exercise different code paths:
#   * Interface names (eth0, wlan0, lo, long names)
#   * Object references with IEC 61850-like tokens and separators ($, .)
#   * Filenames/paths suitable for FUZZ_PARAM_FILENAME consumer
#   * Hostnames/IP literals
#   * Short/long visible strings, alnum/underscore for MMS names
#   * Hex-like strings for MAC material
# - Keep total size <= 4096 bytes.

SAFE_CHARS = string.ascii_letters + string.digits + "_-.$"  # common for names/refs
ALNUM_UNDERSCORE = string.ascii_letters + string.digits + "_"


def _rand_choice(rng, items):
    return items[rng.randrange(len(items))]


def _rand_str(rng, min_len, max_len, alphabet):
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(alphabet) for _ in range(n))


def _rand_hostname(rng):
    # Mix of hostname labels and optional domain
    labels = rng.randint(1, 3)
    parts = []
    for _ in range(labels):
        parts.append(_rand_str(rng, 1, 10, string.ascii_lowercase + string.digits + "-"))
    return ".".join(parts)


def _rand_ipv4(rng):
    return ".".join(str(rng.randint(0, 255)) for _ in range(4))


def _rand_iface(rng):
    presets = [
        "eth0", "eth1", "wlan0", "lo", "enp0s3", "eno1", "br0", "tap0",
        "vlan10", "bond0", "docker0",
    ]
    if rng.random() < 0.5:
        return _rand_choice(rng, presets)
    base = _rand_choice(rng, ["eth", "enp", "eno", "wlan", "tap", "vlan"]) + str(rng.randint(0, 999))
    return base[:64]


def _rand_objref(rng):
    # Build IEC 61850-like object refs and dataset names
    # Examples: "LD0/LLN0$DS1", "MMXU1$ST$InstMag.i", "LD1/CSWI1.Pos.stVal"
    ld = _rand_str(rng, 2, 6, ALNUM_UNDERSCORE) + str(rng.randint(0, 2))
    ln = _rand_choice(rng, ["LLN0", "MMXU1", "CSWI1", "PTOC1", "GGIO1"]) 
    tail_type = rng.randint(0, 3)
    if tail_type == 0:
        # dataset ref
        ds = _rand_str(rng, 2, 6, ALNUM_UNDERSCORE)
        return f"{ld}/{ln}$DS{rng.randint(1,3)}_{ds}"
    elif tail_type == 1:
        fc = _rand_choice(rng, ["ST", "MX", "SP", "CF", "DC", "SE"]) 
        comp = _rand_choice(rng, ["stVal", "q", "t", "Mag", "InstMag.i"]) 
        return f"{ld}/{ln}${fc}${comp}"
    elif tail_type == 2:
        return f"{ld}/{ln}.Pos.stVal"
    else:
        return f"{ld}/{ln}"


def _rand_filename(rng):
    # Generate POSIX-like relative file path
    dirs = [
        _rand_choice(rng, ["/tmp", "/var/tmp", "/var/log", "/home/user", "/etc"]) ,
        _rand_str(rng, 1, 8, ALNUM_UNDERSCORE).lower()
    ]
    name = _rand_str(rng, 1, 10, ALNUM_UNDERSCORE)
    ext = _rand_choice(rng, [".bin", ".dat", ".txt", ".cfg", ".log"]) if rng.random() < 0.7 else ""
    return "/".join(d.strip("/") for d in dirs) + "/" + name + ext


def _rand_visible_string(rng):
    # Generic visible string up to 128
    return _rand_str(rng, 1, 128, string.printable.replace("\x0b", "").replace("\x0c", "").replace("\x0b", ""))


def _rand_mms_name(rng):
    # [A-Za-z_][A-Za-z0-9_]*
    first = rng.choice(string.ascii_letters + "_")
    rest = _rand_str(rng, 0, 15, ALNUM_UNDERSCORE)
    return first + rest


def _rand_mac_string(rng):
    # 6 bytes worth of chars useful for MAC dst address extraction
    return "".join(chr(rng.randint(0, 255)) for _ in range(6))


def _rand_tls_id(rng):
    # GoID/GoCbRef/SvID-like tags
    base = _rand_choice(rng, ["GOID", "GCB", "SV", "ID"]) + str(rng.randint(0, 9999))
    return base


def _append_cstr(buf: bytearray, s: str):
    # Ensure we never embed NUL in mid unless intended; for arbitrary strings we allow arbitrary content.
    if isinstance(s, str):
        data = s.encode('utf-8', 'ignore')
    else:
        data = bytes(s)
    buf.extend(data)
    buf.append(0)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    out = bytearray()

    # Compose a sequence of strings in an order that helps many stubs early on
    # 1) Interface names and MAC material
    for _ in range(rng.randint(2, 5)):
        _append_cstr(out, _rand_iface(rng))
    _append_cstr(out, _rand_mac_string(rng))  # raw bytes then NUL

    # 2) Hostnames and IPs (for connections)
    for _ in range(rng.randint(1, 3)):
        _append_cstr(out, _rand_hostname(rng))
    _append_cstr(out, _rand_ipv4(rng))

    # 3) IEC 61850 object references and dataset-like names
    for _ in range(rng.randint(3, 6)):
        _append_cstr(out, _rand_objref(rng))

    # 4) Filenames for FUZZ_PARAM_FILENAME consumers
    for _ in range(rng.randint(1, 3)):
        _append_cstr(out, _rand_filename(rng))

    # 5) Generic visible strings and MMS-friendly names
    for _ in range(rng.randint(3, 6)):
        _append_cstr(out, _rand_visible_string(rng))
    for _ in range(rng.randint(3, 6)):
        _append_cstr(out, _rand_mms_name(rng))

    # 6) GoID/GCB/IDs and dataset IDs
    for _ in range(rng.randint(2, 4)):
        _append_cstr(out, _rand_tls_id(rng))

    # 7) Extra: likely dataset names and report IDs
    _append_cstr(out, "LN0$DS1")
    _append_cstr(out, "Report01")

    # Keep within 4096 bytes
    if len(out) > 4096:
        out = out[:4095]  # ensure last byte not mid-multi-byte; safe for our ASCII-heavy content

    return bytes(out)
